<?php
declare(strict_types=1);
final class AdminAcademicModel
{
 public function dashboard():array{$d=Database::connection();$periods=$d->query('SELECT *, (SELECT COUNT(*) FROM student_enrollments se WHERE se.academic_period_id=academic_periods.id) students FROM academic_periods ORDER BY starts_on DESC')->fetchAll();$source=null;$targets=[];foreach($periods as $p){if($p['status']==='active')$source=$p;if($p['status']==='planned')$targets[]=$p;}return ['periods'=>$periods,'careers'=>$d->query('SELECT * FROM careers ORDER BY name')->fetchAll(),'types'=>$d->query('SELECT * FROM project_types ORDER BY name')->fetchAll(),'lines'=>$d->query('SELECT rl.*,c.name career_name FROM research_lines rl LEFT JOIN careers c ON c.id=rl.career_id ORDER BY rl.name')->fetchAll(),'subjects'=>$d->query('SELECT s.*,c.name career_name,p.name period_name,u.full_name teacher_name FROM academic_subjects s JOIN careers c ON c.id=s.career_id JOIN academic_periods p ON p.id=s.academic_period_id LEFT JOIN users u ON u.id=s.responsible_teacher_id ORDER BY p.starts_on DESC,s.semester,s.name')->fetchAll(),'teachers'=>$d->query("SELECT u.id,u.full_name FROM users u JOIN teacher_profiles t ON t.user_id=u.id WHERE u.status='active' ORDER BY u.full_name")->fetchAll(),'promotion'=>['source'=>$source,'targets'=>$targets,'students'=>$source?(int)$source['students']:0]];}
 public function save(string $entity,array $v,int $actor):void{if(!in_array($entity,['period','career','type','line','subject'],true))throw new InvalidArgumentException('El catálogo seleccionado no es válido.');Database::transaction(function(PDO $d)use($entity,$v,$actor):void{$id=(int)($v['id']??0);if($entity==='period'){$name=trim((string)($v['name']??''));$code=trim((string)($v['code']??''));$start=(string)($v['starts_on']??'');$end=(string)($v['ends_on']??'');if(!$name||!$code||!$start||!$end||$end<$start)throw new InvalidArgumentException('Completa correctamente el periodo y sus fechas.');$q=$id?$d->prepare('UPDATE academic_periods SET code=:code,name=:name,starts_on=:start,ends_on=:end WHERE id=:id'):$d->prepare("INSERT INTO academic_periods(code,name,starts_on,ends_on,status) VALUES(:code,:name,:start,:end,'planned')");$x=['code'=>$code,'name'=>$name,'start'=>$start,'end'=>$end]+($id?['id'=>$id]:[]);$q->execute($x);}elseif(in_array($entity,['career','type','line'],true)){$name=trim((string)($v['name']??''));if(mb_strlen($name)<3)throw new InvalidArgumentException('Ingresa un nombre válido.');$table=['career'=>'careers','type'=>'project_types','line'=>'research_lines'][$entity];if($entity==='line'){$q=$id?$d->prepare('UPDATE research_lines SET name=:name,career_id=:career WHERE id=:id'):$d->prepare('INSERT INTO research_lines(name,career_id) VALUES(:name,:career)');$x=['name'=>$name,'career'=>(int)($v['career_id']??0)?:null]+($id?['id'=>$id]:[]);}else{$code=trim((string)($v['code']??''));if(!$code)throw new InvalidArgumentException('Ingresa un código.');$q=$id?$d->prepare("UPDATE $table SET code=:code,name=:name WHERE id=:id"):$d->prepare("INSERT INTO $table(code,name) VALUES(:code,:name)");$x=['code'=>$code,'name'=>$name]+($id?['id'=>$id]:[]);}$q->execute($x);}else{$name=trim((string)($v['name']??''));$code=trim((string)($v['code']??''));$career=(int)($v['career_id']??0);$period=(int)($v['academic_period_id']??0);$semester=(int)($v['semester']??0);if(!$name||!$code||$career<1||$period<1||$semester<1||$semester>10)throw new InvalidArgumentException('Completa los datos de la asignatura.');$q=$id?$d->prepare('UPDATE academic_subjects SET code=:code,name=:name,career_id=:career,academic_period_id=:period,semester=:semester,responsible_teacher_id=:teacher WHERE id=:id'):$d->prepare('INSERT INTO academic_subjects(code,name,career_id,academic_period_id,semester,responsible_teacher_id) VALUES(:code,:name,:career,:period,:semester,:teacher)');$x=['code'=>$code,'name'=>$name,'career'=>$career,'period'=>$period,'semester'=>$semester,'teacher'=>(int)($v['teacher_id']??0)?:null]+($id?['id'=>$id]:[]);$q->execute($x);}$this->audit($d,$actor,'academic_'.$entity.'_saved',$entity,$id?:null);});}
 public function promote(int $target,int $actor):array{if($target<1)throw new InvalidArgumentException('Selecciona el nuevo periodo.');return Database::transaction(function(PDO $d)use($target,$actor):array{$source=$d->query("SELECT id FROM academic_periods WHERE status='active' LIMIT 1 FOR UPDATE")->fetchColumn();if(!$source)throw new InvalidArgumentException('No existe un periodo activo.');$q=$d->prepare("SELECT id FROM academic_periods WHERE id=:id AND status='planned' FOR UPDATE");$q->execute(['id'=>$target]);if(!$q->fetchColumn())throw new InvalidArgumentException('El periodo de destino no está disponible.');$rows=$d->query("SELECT * FROM student_enrollments WHERE academic_period_id=".(int)$source." AND status='active' FOR UPDATE")->fetchAll();$promoted=0;$completed=0;foreach($rows as $r){$d->prepare("UPDATE student_enrollments SET status='completed' WHERE id=:id")->execute(['id'=>$r['id']]);if((int)$r['semester']>=10){$completed++;continue;}$d->prepare("INSERT INTO student_enrollments(student_id,academic_period_id,career_id,semester,status) VALUES(:student,:period,:career,:semester,'active')")->execute(['student'=>$r['student_id'],'period'=>$target,'career'=>$r['career_id'],'semester'=>(int)$r['semester']+1]);$promoted++;}$d->prepare("UPDATE academic_periods SET status='closed' WHERE id=:id")->execute(['id'=>$source]);$d->prepare("UPDATE academic_periods SET status='active' WHERE id=:id")->execute(['id'=>$target]);$this->audit($d,$actor,'academic_period_promoted','period',$target,['source'=>$source,'promoted'=>$promoted,'completed'=>$completed]);return compact('promoted','completed');});}
 private function audit(PDO $d,int $actor,string $action,string $type,?int $id,array $details=[]):void{$q=$d->prepare('INSERT INTO admin_audit_log(actor_user_id,action,entity_type,entity_id,details) VALUES(:actor,:action,:type,:id,:details)');$q->execute(['actor'=>$actor,'action'=>$action,'type'=>$type,'id'=>$id,'details'=>json_encode($details)]);}
}
